.opis {
  color: var(--tekst-slaby);
  margin-top: 0;
  margin-bottom: 24px;
}

.opis code {
  background: var(--linia);
  padding: 1px 5px;
  border-radius: 4px;
}

.karta {
  background: var(--plytka);
  border: 1px solid var(--plytka-obrys);
  border-radius: 14px;
  box-shadow: var(--plytka-cien);
  padding: 16px 18px;
  margin-bottom: 16px;
}

.karta.blok-numerowany:hover {
  background: var(--plytka-hover);
  box-shadow: var(--plytka-cien-hover);
}

.blok-numerowany:not(.karta) {
  outline: 1px dashed var(--blok-kontur);
  outline-offset: 6px;
  border-radius: 10px;
}

.blok-numerowany:not(.karta):hover {
  outline: 2px solid var(--blok-kontur-hover);
  background: var(--blok-tlo-hover);
}

