}

.var-zakres-btn.aktywny {
  background: var(--akcent);
  color: var(--akcent-tekst);
  border-color: var(--akcent);
}

body.t-strona .t-tresc .sp-zakl {
  padding: 4px 12px; font-size: 12px; border-radius: 3px 3px 0 0; background: transparent;
  color: var(--tekst-slaby); border: 1px solid transparent; border-bottom: 0; cursor: pointer;
}
